            accept: ['select * from orders order by total_sar desc limit 3', 'select * from orders order by total_sar desc limit 3;', 'select * from orders order by total_sar desc limit 3 ;'],
            solution: { en: 'SELECT * FROM orders ORDER BY total_sar DESC LIMIT 3; — sort descending on the metric, then keep the head. Result: orders 104, 101, 102.', ar: 'SELECT * FROM orders ORDER BY total_sar DESC LIMIT 3; — رتّب تنازلياً على المقياس ثم احفظ الرأس. النتيجة: الطلبات 104 و101 و102.' },
